import type { Comanda } from "@/types/cocinero";
import Badge from "@/components/ui/badge";

interface ComandaCardProps {
  comanda: Comanda;
  onClick: (comanda: Comanda) => void;
}

export default function ComandaCard({ comanda, onClick }: ComandaCardProps) {
  const bgColores = {
    pendiente: "bg-yellow-50 border-yellow-500",
    en_cocina: "bg-blue-50 border-blue-500",
    listo: "bg-green-50 border-green-500",
    cancelado: "bg-gray-50 border-gray-500",
  };

  const badgeVariants: Record<
    string,
    "success" | "danger" | "warning" | "info"
  > = {
    pendiente: "warning",
    en_cocina: "info",
    listo: "success",
    cancelado: "info",
  };

  return (
    <div
      className="
    bg-white
    border border-gray-300
    rounded-lg
    p-4
    font-mono
    shadow-md
    space-y-3
    text-sm
  "
    >
      {/* HEADER */}
      <div className="flex justify-between items-center border-b border-gray-400 pb-2">
        <div>
          <p className="font-bold text-base">Comanda Mesa {comanda.mesa.id}</p>
          <p className="text-xs text-gray-500">{comanda.hora}</p>
        </div>

        <span className="text-xs uppercase tracking-wide font-semibold">
          {comanda.estado}
        </span>
      </div>

      {/* PLATILLOS */}
      <div>
        <div className="flex justify-between font-bold border-b border-gray-300 pb-1 text-sm">
          <span>Cant.</span>
          <span>Platillos</span>
        </div>

        {comanda.detalles
          .filter((d) => d.menu.tipo === "Plato de Fondo")
          .map((d) => (
            <div key={d.id_menu} className="flex justify-between py-1 text-sm">
              <span className="font-semibold">{d.cantidad}</span>

              <span className="text-right flex-1 ml-3">
                {d.menu.nombre}
                {d.observacion && (
                  <p className="text-xs italic text-gray-500 mt-0.5">
                    {d.observacion}
                  </p>
                )}
              </span>
            </div>
          ))}
      </div>

      {/* BEBIDAS */}
      <div>
        <div className="flex justify-between font-bold border-b border-gray-300 pb-1 text-sm">
          <span>Cant.</span>
          <span>Bebidas</span>
        </div>

        {comanda.detalles
          .filter((d) => d.menu.tipo === "Bebida")
          .map((d) => (
            <div key={d.id_menu} className="flex justify-between py-1 text-sm">
              <span className="font-semibold">{d.cantidad}</span>
              <span className="text-right flex-1 ml-3">{d.menu.nombre}</span>
            </div>
          ))}
      </div>

      {/* FOOTER */}
      <div className="border-t border-gray-400 pt-2 text-xs text-gray-600">
        <p>
          Mesa: {comanda.mesa.nombre} · {comanda.mesa.capacidad} pers
        </p>
        <p>Ubicación: {comanda.mesa.ubicacion}</p>
      </div>

      {/* ACCIONES */}
      <div className="flex gap-3 pt-3">
        <button
          className="
        flex-1
        border border-gray-400
        py-2
        text-sm
        rounded-md
        hover:bg-gray-100
        transition
      "
        >
          Listo
        </button>

        <button
          className="
        flex-1
        border border-gray-400
        py-2
        text-sm
        rounded-md
        hover:bg-gray-100
        transition
      "
        >
          Transferir
        </button>
      </div>
    </div>
  );
}
